add_action( 'woocommerce_after_checkout_billing_form', 'perfectpixel_checkout_honeypot_field' );
add_action( 'woocommerce_after_checkout_validation', 'perfectpixel_checkout_honeypot_check', 10, 2 );

function perfectpixel_checkout_honeypot_field() {
	echo '<div style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden" aria-hidden="true">';
	echo '<label for="perfectpixel_hp_website">Website</label>';
	echo '<input type="text" id="perfectpixel_hp_website" name="perfectpixel_hp_website" value="" tabindex="-1" autocomplete="off">';
	echo '</div>';
}

function perfectpixel_checkout_honeypot_check( $data, $errors ) {
	if ( ! empty( $_POST['perfectpixel_hp_website'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		$errors->add( 'perfectpixel_honeypot', esc_html( '{{honeypot_message}}' ) );
	}
}
